import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const p=JSON.parse('{"title":"参加周末派对","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/dialogues/03-weekend-party.md","filePath":"zh/more/maltese/practice/dialogues/03-weekend-party.md"}'),e={name:"zh/more/maltese/practice/dialogues/03-weekend-party.md"},i=r('<h1 id="参加周末派对" tabindex="-1">参加周末派对 <a class="header-anchor" href="#参加周末派对" aria-label="Permalink to &quot;参加周末派对&quot;">​</a></h1><p><strong>场景：</strong> 两位朋友商量参加周末派对的安排。</p><h2 id="完整对话" tabindex="-1">完整对话 <a class="header-anchor" href="#完整对话" aria-label="Permalink to &quot;完整对话&quot;">​</a></h2><p><strong>Anna：</strong> Se tagħmel xi ħaġa fi tmiem il-ġimgħa?</p><p><strong>Mark：</strong> Għadni ma ddeċidejtx. Għaliex?</p><p><strong>Anna：</strong> Qed norganizza festa d-dar is-Sibt filgħaxija.</p><p><strong>Mark：</strong> Ħsejjes sbieħ! F&#39;liema ħin tibda?</p><p><strong>Anna：</strong> Nibdew fit-tmienja, imma tista&#39; tasal aktar tard.</p><p><strong>Mark：</strong> X&#39;għandi nġib miegħi?</p><p><strong>Anna：</strong> Ġib xi ħaġa x&#39;tixorbu u jien nagħmel l-ikel.</p><p><strong>Mark：</strong> Perfett. Inkun hemm fit-tmienja.</p><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><h3 id="_1-anna" tabindex="-1">1. Anna <a class="header-anchor" href="#_1-anna" aria-label="Permalink to &quot;1. Anna&quot;">​</a></h3><p><strong>Malti:</strong> Se tagħmel xi ħaġa fi tmiem il-ġimgħa?</p><p><strong>整句：</strong> 你周末有什么安排吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Se</td><td>将；会</td><td>这里与未完成式连用，询问计划</td></tr><tr><td>tagħmel</td><td>你做</td><td>第二人称单数形式</td></tr><tr><td>xi</td><td>某个；一些</td><td>用于询问是否有安排</td></tr><tr><td>ħaġa</td><td>事情</td><td>阴性名词</td></tr><tr><td>fi</td><td>在</td><td>介词，后接时间</td></tr><tr><td>tmiem</td><td>结束；末尾</td><td>阳性名词</td></tr><tr><td>il-ġimgħa</td><td>一周；星期</td><td><code>tmiem il-ġimgħa</code> 整体表示周末</td></tr></tbody></table><h3 id="_2-mark" tabindex="-1">2. Mark <a class="header-anchor" href="#_2-mark" aria-label="Permalink to &quot;2. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Għadni ma ddeċidejtx. Għaliex?</p><p><strong>整句：</strong> 我还没决定。怎么了？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għadni</td><td>我仍然；我还</td><td><code>għad</code>“仍然” + <code>-ni</code> 第一人称后缀</td></tr><tr><td>ma</td><td>不</td><td>否定结构的一部分，常与句末 <code>x</code> 配合</td></tr><tr><td>ddeċidejtx</td><td>我没有决定</td><td>完成式否定形式；词尾 <code>-x</code> 标记否定</td></tr><tr><td>Għaliex</td><td>为什么</td><td>疑问词</td></tr></tbody></table><h3 id="_3-anna" tabindex="-1">3. Anna <a class="header-anchor" href="#_3-anna" aria-label="Permalink to &quot;3. Anna&quot;">​</a></h3><p><strong>Malti:</strong> Qed norganizza festa d-dar is-Sibt filgħaxija.</p><p><strong>整句：</strong> 我正在组织星期六晚上在家举行的派对。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Qed</td><td>正在</td><td>与动词未完成式一起构成进行表达</td></tr><tr><td>norganizza</td><td>我组织</td><td>第一人称单数形式</td></tr><tr><td>festa</td><td>派对；庆祝活动</td><td>阴性名词</td></tr><tr><td>d-dar</td><td>在家；家里</td><td><code>id-dar</code> 的常见缩合写法</td></tr><tr><td>is-Sibt</td><td>星期六</td><td>常带定冠词</td></tr><tr><td>filgħaxija</td><td>在晚上</td><td>时间表达</td></tr></tbody></table><h3 id="_4-mark" tabindex="-1">4. Mark <a class="header-anchor" href="#_4-mark" aria-label="Permalink to &quot;4. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Ħsejjes sbieħ! F&#39;liema ħin tibda?</p><p><strong>整句：</strong> 听起来不错！几点开始？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ħsejjes</td><td>听起来</td><td>第三人称形式，字面关联“声音”</td></tr><tr><td>sbieħ</td><td>好听的；不错的</td><td>阳性复数形式/固定搭配</td></tr><tr><td>F&#39;liema</td><td>在什么</td><td><code>f&#39;</code>“在” + <code>liema</code>“哪一个/什么”</td></tr><tr><td>ħin</td><td>时间</td><td>阳性名词</td></tr><tr><td>tibda</td><td>你开始；它开始</td><td>形式可由主语决定，此处指派对开始</td></tr></tbody></table><h3 id="_5-anna" tabindex="-1">5. Anna <a class="header-anchor" href="#_5-anna" aria-label="Permalink to &quot;5. Anna&quot;">​</a></h3><p><strong>Malti:</strong> Nibdew fit-tmienja, imma tista&#39; tasal aktar tard.</p><p><strong>整句：</strong> 我们八点开始，不过你可以晚一点到。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nibdew</td><td>我们开始</td><td>第一人称复数形式</td></tr><tr><td>fit-tmienja</td><td>在八点</td><td><code>f&#39;</code> + 定冠词钟点形式的缩合</td></tr><tr><td>imma</td><td>但是；不过</td><td>连词</td></tr><tr><td>tista&#39;</td><td>你可以</td><td>第二人称单数形式</td></tr><tr><td>tasal</td><td>你到达</td><td>第二人称单数形式</td></tr><tr><td>aktar</td><td>更；较</td><td>比较副词</td></tr><tr><td>tard</td><td>晚；迟</td><td>副词/形容词</td></tr></tbody></table><h3 id="_6-mark" tabindex="-1">6. Mark <a class="header-anchor" href="#_6-mark" aria-label="Permalink to &quot;6. Mark&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;għandi nġib miegħi?</p><p><strong>整句：</strong> 我应该带些什么？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>X&#39;</td><td>什么</td><td>疑问词缩写</td></tr><tr><td>għandi</td><td>我有；我应该</td><td>此处和后面的动词一起表达“我该……”</td></tr><tr><td>nġib</td><td>我带来</td><td>第一人称单数形式</td></tr><tr><td>miegħi</td><td>和我一起；随身</td><td><code>miegħ</code>“和” + <code>-i</code>“我”</td></tr></tbody></table><h3 id="_7-anna" tabindex="-1">7. Anna <a class="header-anchor" href="#_7-anna" aria-label="Permalink to &quot;7. Anna&quot;">​</a></h3><p><strong>Malti:</strong> Ġib xi ħaġa x&#39;tixorbu u jien nagħmel l-ikel.</p><p><strong>整句：</strong> 带点喝的东西来，我来准备食物。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ġib</td><td>带来</td><td>对一人的命令式</td></tr><tr><td>xi</td><td>一些</td><td>不定限定词</td></tr><tr><td>ħaġa</td><td>东西</td><td>阴性名词</td></tr><tr><td>x&#39;</td><td>可以……的；要……的</td><td>引出修饰前面名词的从句</td></tr><tr><td>tixorbu</td><td>你们喝；大家喝</td><td><code>tixorbu</code> 是复数形式；此处指来宾</td></tr><tr><td>u</td><td>和；而</td><td>连词</td></tr><tr><td>jien</td><td>我</td><td>强调代词</td></tr><tr><td>nagħmel</td><td>我做；我准备</td><td>第一人称单数形式</td></tr><tr><td>l-ikel</td><td>食物</td><td>定冠词 + <code>ikel</code></td></tr></tbody></table><h3 id="_8-mark" tabindex="-1">8. Mark <a class="header-anchor" href="#_8-mark" aria-label="Permalink to &quot;8. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Perfett. Inkun hemm fit-tmienja.</p><p><strong>整句：</strong> 太好了。我八点会到那里。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Perfett</td><td>太好了；完美</td><td>阳性形式的形容词，也作感叹语</td></tr><tr><td>Inkun</td><td>我会是；我会在</td><td>第一人称单数形式</td></tr><tr><td>hemm</td><td>那里；在场</td><td>地点副词</td></tr><tr><td>fit-tmienja</td><td>在八点</td><td>时间表达</td></tr></tbody></table><h2 id="口语替换" tabindex="-1">口语替换 <a class="header-anchor" href="#口语替换" aria-label="Permalink to &quot;口语替换&quot;">​</a></h2><ul><li><code>il-Ġimgħa filgħaxija</code>：星期五晚上。</li><li><code>Nista&#39; nġib deżerta?</code>：我可以带甜点吗？</li><li><code>Narawk is-Sibt.</code>：星期六见。</li></ul>',46),n=[i];function o(h,l,s,m,c,b){return d(),a("div",null,n)}const k=t(e,[["render",o]]);export{p as __pageData,k as default};
